import json
obs00 = json.load(open('win_0_5/observation_00.json'))
obs01 = json.load(open('win_0_5/observation_01.json'))

# Find purple observations with timestamps
for obs in obs00['result']['observations']:
    if 'purple' in obs['observation'].lower():
        print(f\"obs00 frame {obs['source_frame_id']} @ {obs['timestamp_sec']}: {obs['observation']}\")

for obs in obs01['result']['observations']:
    if 'purple' in obs['observation'].lower():
        print(f\"obs01 frame {obs['source_frame_id']} @ {obs['timestamp_sec']}: {obs['observation']}\")
"

